using Microsoft.AspNetCore.Authorization;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Data;
using System.Security.Claims;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments");

        // Dispatchers: get all shipments
        group.MapGet("/", [Authorize(Roles = "Dispatcher")] async (ApplicationDbContext db) =>
        {
            var shipments = await db.Shipments
                .OrderByDescending(s => s.CreatedAt)
                .Select(s => ToDto(s))
                .ToListAsync();
            return Results.Ok(shipments);
        });

        // Customers: get their own shipments
        group.MapGet("/mine", [Authorize] async (ApplicationDbContext db, ClaimsPrincipal user) =>
        {
            var userId = user.FindFirstValue(ClaimTypes.NameIdentifier)!;
            var shipments = await db.Shipments
                .Where(s => s.CustomerId == userId)
                .OrderByDescending(s => s.CreatedAt)
                .Select(s => ToDto(s))
                .ToListAsync();
            return Results.Ok(shipments);
        });

        // Public tracking by tracking number
        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments
                .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
            if (shipment is null) return Results.NotFound();
            return Results.Ok(new TrackingResult
            {
                TrackingNumber = shipment.TrackingNumber,
                Status = (ShipmentTracker.Client.Models.ShipmentStatus)(int)shipment.Status,
                Origin = shipment.Origin,
                Destination = shipment.Destination,
                EstimatedDelivery = shipment.EstimatedDelivery,
                ActualDelivery = shipment.ActualDelivery,
                CreatedAt = shipment.CreatedAt
            });
        });

        // Dispatchers: update shipment status
        group.MapPut("/{id}/status", [Authorize(Roles = "Dispatcher")] async (int id, UpdateShipmentStatusRequest request, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null) return Results.NotFound();

            shipment.Status = (Data.ShipmentStatus)(int)request.Status;
            if (request.Notes is not null) shipment.Notes = request.Notes;
            if (request.EstimatedDelivery.HasValue) shipment.EstimatedDelivery = request.EstimatedDelivery;
            if (request.Status == ShipmentTracker.Client.Models.ShipmentStatus.Delivered)
                shipment.ActualDelivery = DateTime.UtcNow;

            await db.SaveChangesAsync();
            return Results.Ok(ToDto(shipment));
        });
    }

    private static ShipmentDto ToDto(Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = (ShipmentTracker.Client.Models.ShipmentStatus)(int)s.Status,
        CreatedAt = s.CreatedAt,
        EstimatedDelivery = s.EstimatedDelivery,
        ActualDelivery = s.ActualDelivery,
        Notes = s.Notes,
        CustomerId = s.CustomerId,
        DispatcherId = s.DispatcherId
    };
}

