@page "/dispatcher"
@rendermode InteractiveAuto
@attribute [Microsoft.AspNetCore.Authorization.Authorize(Roles = "Dispatcher")]
@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<h1>Shipment Dashboard</h1>

<div class="mb-3">
    <input type="text" class="form-control" placeholder="Filter by destination..."
           @bind="filterText" @bind:event="oninput" />
</div>

@if (shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else if (!FilteredShipments.Any())
{
    <p>No shipments found.</p>
}
else
{
    <table class="table table-striped table-hover">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Est. Delivery</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var shipment in FilteredShipments)
            {
                <tr>
                    <td>@shipment.TrackingNumber</td>
                    <td>@shipment.Origin</td>
                    <td>@shipment.Destination</td>
                    <td>
                        <span class="badge @GetStatusBadgeClass(shipment.Status)">
                            @shipment.Status
                        </span>
                    </td>
                    <td>@shipment.EstimatedDelivery?.ToString("MMM dd, yyyy")</td>
                    <td>
                        <button class="btn btn-sm btn-primary" @onclick="() => StartEdit(shipment)">
                            Update
                        </button>
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@if (editingShipment is not null)
{
    <div class="modal d-block" tabindex="-1" style="background-color: rgba(0,0,0,0.5)">
        <div class="modal-dialog">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Update Shipment @editingShipment.TrackingNumber</h5>
                    <button type="button" class="btn-close" @onclick="CancelEdit"></button>
                </div>
                <div class="modal-body">
                    <div class="mb-3">
                        <label class="form-label">Status</label>
                        <select class="form-select" @bind="newStatus">
                            @foreach (var status in Enum.GetValues<ShipmentStatus>())
                            {
                                <option value="@status">@status</option>
                            }
                        </select>
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Estimated Delivery</label>
                        <input type="date" class="form-control" @bind="newEstimatedDelivery" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Notes</label>
                        <textarea class="form-control" @bind="newNotes" rows="3"></textarea>
                    </div>
                </div>
                <div class="modal-footer">
                    <button class="btn btn-secondary" @onclick="CancelEdit">Cancel</button>
                    <button class="btn btn-primary" @onclick="SaveStatus" disabled="@saving">
                        @(saving ? "Saving..." : "Save")
                    </button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    private List<ShipmentDto>? shipments;
    private string filterText = string.Empty;
    private ShipmentDto? editingShipment;
    private ShipmentStatus newStatus;
    private DateTime? newEstimatedDelivery;
    private string? newNotes;
    private bool saving;

    private IEnumerable<ShipmentDto> FilteredShipments =>
        shipments?.Where(s => string.IsNullOrEmpty(filterText) ||
            s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)) ?? [];

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private void StartEdit(ShipmentDto shipment)
    {
        editingShipment = shipment;
        newStatus = shipment.Status;
        newEstimatedDelivery = shipment.EstimatedDelivery;
        newNotes = shipment.Notes;
    }

    private void CancelEdit() => editingShipment = null;

    private async Task SaveStatus()
    {
        if (editingShipment is null) return;
        saving = true;
        var result = await ShipmentService.UpdateStatusAsync(editingShipment.Id, new UpdateShipmentStatusRequest
        {
            Status = newStatus,
            Notes = newNotes,
            EstimatedDelivery = newEstimatedDelivery
        });
        if (result is not null)
        {
            var index = shipments!.FindIndex(s => s.Id == result.Id);
            if (index >= 0) shipments[index] = result;
        }
        saving = false;
        editingShipment = null;
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/my-shipments"
@rendermode InteractiveAuto
@attribute [Microsoft.AspNetCore.Authorization.Authorize]
@inject IShipmentService ShipmentService

<PageTitle>My Shipments</PageTitle>

<h1>My Shipments</h1>

@if (shipments is null)
{
    <p><em>Loading your shipments...</em></p>
}
else if (!shipments.Any())
{
    <p>You have no shipments yet.</p>
}
else
{
    <div class="row">
        @foreach (var shipment in shipments)
        {
            <div class="col-md-6 col-lg-4 mb-3">
                <div class="card @(shipment.Status == ShipmentStatus.Delivered ? "border-success" : "")">
                    <div class="card-header d-flex justify-content-between">
                        <strong>@shipment.TrackingNumber</strong>
                        <span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span>
                    </div>
                    <div class="card-body">
                        <p class="mb-1"><strong>From:</strong> @shipment.Origin</p>
                        <p class="mb-1"><strong>To:</strong> @shipment.Destination</p>
                        @if (shipment.EstimatedDelivery.HasValue)
                        {
                            <p class="mb-1"><strong>Estimated Delivery:</strong> @shipment.EstimatedDelivery.Value.ToString("MMM dd, yyyy")</p>
                        }
                        @if (shipment.ActualDelivery.HasValue)
                        {
                            <p class="mb-1 text-success"><strong>Delivered:</strong> @shipment.ActualDelivery.Value.ToString("MMM dd, yyyy HH:mm")</p>
                        }
                        @if (!string.IsNullOrEmpty(shipment.Notes))
                        {
                            <p class="mb-0 text-muted"><small>@shipment.Notes</small></p>
                        }
                    </div>
                </div>
            </div>
        }
    </div>
}

<hr />
<h3>Track a Shipment</h3>
<div class="input-group mb-3" style="max-width: 500px;">
    <input type="text" class="form-control" placeholder="Enter tracking number"
           @bind="trackingNumber" @onkeydown="HandleKeyDown" />
    <button class="btn btn-outline-primary" @onclick="TrackShipment" disabled="@tracking">
        @(tracking ? "Tracking..." : "Track")
    </button>
</div>

@if (trackingResult is not null)
{
    <div class="card mt-3" style="max-width: 500px;">
        <div class="card-body">
            <h5>@trackingResult.TrackingNumber</h5>
            <p>Status: <span class="badge @GetStatusBadgeClass(trackingResult.Status)">@trackingResult.Status</span></p>
            <p>From: @trackingResult.Origin → To: @trackingResult.Destination</p>
            @if (trackingResult.EstimatedDelivery.HasValue)
            {
                <p>Estimated Delivery: @trackingResult.EstimatedDelivery.Value.ToString("MMM dd, yyyy")</p>
            }
        </div>
    </div>
}
else if (trackingSearched && !tracking)
{
    <div class="alert alert-warning" style="max-width: 500px;">Shipment not found.</div>
}

@code {
    private List<ShipmentDto>? shipments;
    private string trackingNumber = string.Empty;
    private TrackingResult? trackingResult;
    private bool tracking;
    private bool trackingSearched;

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetMyShipmentsAsync();
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter") await TrackShipment();
    }

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        tracking = true;
        trackingSearched = true;
        trackingResult = await ShipmentService.TrackShipmentAsync(trackingNumber.Trim());
        tracking = false;
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/track"
@rendermode InteractiveAuto
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h1>Track Your Shipment</h1>
<p>Enter your tracking number below to check the current status and estimated delivery.</p>

<div class="input-group mb-3" style="max-width: 500px;">
    <input type="text" class="form-control" placeholder="e.g. TRK-20260101-001"
           @bind="trackingNumber" @onkeydown="HandleKeyDown" />
    <button class="btn btn-primary" @onclick="TrackShipment" disabled="@tracking">
        @(tracking ? "Searching..." : "Track")
    </button>
</div>

@if (result is not null)
{
    <div class="card mt-4" style="max-width: 600px;">
        <div class="card-header">
            <strong>@result.TrackingNumber</strong>
        </div>
        <div class="card-body">
            <div class="row mb-2">
                <div class="col-4 fw-bold">Status:</div>
                <div class="col-8">
                    <span class="badge @GetStatusBadgeClass(result.Status) fs-6">@result.Status</span>
                </div>
            </div>
            <div class="row mb-2">
                <div class="col-4 fw-bold">Origin:</div>
                <div class="col-8">@result.Origin</div>
            </div>
            <div class="row mb-2">
                <div class="col-4 fw-bold">Destination:</div>
                <div class="col-8">@result.Destination</div>
            </div>
            <div class="row mb-2">
                <div class="col-4 fw-bold">Shipped:</div>
                <div class="col-8">@result.CreatedAt.ToString("MMM dd, yyyy")</div>
            </div>
            @if (result.EstimatedDelivery.HasValue)
            {
                <div class="row mb-2">
                    <div class="col-4 fw-bold">Est. Delivery:</div>
                    <div class="col-8">@result.EstimatedDelivery.Value.ToString("MMM dd, yyyy")</div>
                </div>
            }
            @if (result.ActualDelivery.HasValue)
            {
                <div class="row mb-2">
                    <div class="col-4 fw-bold">Delivered:</div>
                    <div class="col-8 text-success">@result.ActualDelivery.Value.ToString("MMM dd, yyyy HH:mm")</div>
                </div>
            }
        </div>
    </div>
}
else if (searched && !tracking)
{
    <div class="alert alert-warning mt-3" style="max-width: 500px;">
        No shipment found with that tracking number. Please check and try again.
    </div>
}

@code {
    private string trackingNumber = string.Empty;
    private TrackingResult? result;
    private bool tracking;
    private bool searched;

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter") await TrackShipment();
    }

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        tracking = true;
        searched = true;
        result = await ShipmentService.TrackShipmentAsync(trackingNumber.Trim());
        tracking = false;
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        _ => "bg-secondary"
    };
}

