                        {
                            <p class="mb-1"><strong>Estimated Delivery:</strong> @shipment.EstimatedDelivery.Value.ToString("MMM dd, yyyy")</p>
                        }
                        @if (shipment.ActualDelivery.HasValue)
                        {
                            <p class="mb-1 text-success"><strong>Delivered:</strong> @shipment.ActualDelivery.Value.ToString("MMM dd, yyyy HH:mm")</p>
                        }
