@page "/track"
@rendermode InteractiveAuto
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h1>Track Your Shipment</h1>
<p>Enter your tracking number below to check the current status and estimated delivery.</p>

<div class="input-group mb-3" style="max-width: 500px;">
    <input type="text" class="form-control" placeholder="e.g. TRK-20260101-001"
           @bind="trackingNumber" @onkeydown="HandleKeyDown" />
    <button class="btn btn-primary" @onclick="TrackShipment" disabled="@tracking">
        @(tracking ? "Searching..." : "Track")
    </button>
</div>

@if (result is not null)
{
    <div class="card mt-4" style="max-width: 600px;">
        <div class="card-header">
            <strong>@result.TrackingNumber</strong>
        </div>
        <div class="card-body">
            <div class="row mb-2">
                <div class="col-4 fw-bold">Status:</div>
                <div class="col-8">
                    <span class="badge @GetStatusBadgeClass(result.Status) fs-6">@result.Status</span>
                </div>
            </div>
            <div class="row mb-2">
                <div class="col-4 fw-bold">Origin:</div>
                <div class="col-8">@result.Origin</div>
            </div>
            <div class="row mb-2">
                <div class="col-4 fw-bold">Destination:</div>
                <div class="col-8">@result.Destination</div>
            </div>
            <div class="row mb-2">
                <div class="col-4 fw-bold">Shipped:</div>
                <div class="col-8">@result.CreatedAt.ToString("MMM dd, yyyy")</div>
            </div>
            @if (result.EstimatedDelivery.HasValue)
            {
                <div class="row mb-2">
                    <div class="col-4 fw-bold">Est. Delivery:</div>
                    <div class="col-8">@result.EstimatedDelivery.Value.ToString("MMM dd, yyyy")</div>
                </div>
            }
            @if (result.ActualDelivery.HasValue)
            {
                <div class="row mb-2">
                    <div class="col-4 fw-bold">Delivered:</div>
                    <div class="col-8 text-success">@result.ActualDelivery.Value.ToString("MMM dd, yyyy HH:mm")</div>
                </div>
            }
        </div>
    </div>
}
else if (searched && !tracking)
{
    <div class="alert alert-warning mt-3" style="max-width: 500px;">
        No shipment found with that tracking number. Please check and try again.
    </div>
}

@code {
    private string trackingNumber = string.Empty;
    private TrackingResult? result;
    private bool tracking;
    private bool searched;

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter") await TrackShipment();
    }

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        tracking = true;
        searched = true;
        result = await ShipmentService.TrackShipmentAsync(trackingNumber.Trim());
        tracking = false;
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        _ => "bg-secondary"
    };
}

