using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Data;

namespace ShipmentTracker.Endpoints;

public static class SeedEndpoints
{
    public static void MapSeedEndpoints(this WebApplication app)
    {
        if (!app.Environment.IsDevelopment()) return;

        app.MapPost("api/seed", async (
            ApplicationDbContext db,
            UserManager<ApplicationUser> userManager,
            RoleManager<IdentityRole> roleManager) =>
        {
            // Create a dispatcher
            var dispatcher = await userManager.FindByEmailAsync("dispatcher@shiptrack.com");
            if (dispatcher is null)
            {
                dispatcher = new ApplicationUser { UserName = "dispatcher@shiptrack.com", Email = "dispatcher@shiptrack.com", EmailConfirmed = true };
                await userManager.CreateAsync(dispatcher, "Dispatch1!");
                await userManager.AddToRoleAsync(dispatcher, "Dispatcher");
            }

            // Create a customer
            var customer = await userManager.FindByEmailAsync("customer@example.com");
            if (customer is null)
            {
                customer = new ApplicationUser { UserName = "customer@example.com", Email = "customer@example.com", EmailConfirmed = true };
                await userManager.CreateAsync(customer, "Customer1!");
                await userManager.AddToRoleAsync(customer, "Customer");
            }

            // Seed shipments if empty
            if (!await db.Shipments.AnyAsync())
            {
                var shipments = new List<Shipment>
                {
                    new() { TrackingNumber = "TRK-20260101-001", Origin = "New York, NY", Destination = "Los Angeles, CA", Status = ShipmentStatus.InTransit, CustomerId = customer.Id, DispatcherId = dispatcher.Id, EstimatedDelivery = DateTime.UtcNow.AddDays(3) },
                    new() { TrackingNumber = "TRK-20260101-002", Origin = "Chicago, IL", Destination = "Miami, FL", Status = ShipmentStatus.Pending, CustomerId = customer.Id, EstimatedDelivery = DateTime.UtcNow.AddDays(5) },
                    new() { TrackingNumber = "TRK-20260101-003", Origin = "Seattle, WA", Destination = "Boston, MA", Status = ShipmentStatus.OutForDelivery, CustomerId = customer.Id, DispatcherId = dispatcher.Id, EstimatedDelivery = DateTime.UtcNow.AddDays(1) },
                    new() { TrackingNumber = "TRK-20260101-004", Origin = "Dallas, TX", Destination = "Denver, CO", Status = ShipmentStatus.Delivered, CustomerId = customer.Id, DispatcherId = dispatcher.Id, EstimatedDelivery = DateTime.UtcNow.AddDays(-1), ActualDelivery = DateTime.UtcNow.AddDays(-1) },
                    new() { TrackingNumber = "TRK-20260101-005", Origin = "San Francisco, CA", Destination = "Phoenix, AZ", Status = ShipmentStatus.Delayed, CustomerId = customer.Id, DispatcherId = dispatcher.Id, EstimatedDelivery = DateTime.UtcNow.AddDays(2), Notes = "Weather delay in transit" },
                };
                db.Shipments.AddRange(shipments);
                await db.SaveChangesAsync();
            }

            return Results.Ok("Seeded successfully");
        });
    }
}

